 private void stats(){heading("Your viewing overview","Watch time counts active playback from this version onward. Pauses, buffering, trailers and private viewing are excluded.");long progress=0;int finished=0;for(Object value:ProfileStore.prefs(this,"watch-history").getAll().values())try{JSONObject record=new JSONObject((String)value);progress+=record.optLong("position");if(record.optBoolean("completed"))finished++;}catch(Exception ignored){}int marked=0;for(java.util.Map.Entry<String,?> entry:PersonalStore.prefs(this).getAll().entrySet())if(entry.getKey().startsWith("watched:")&&Boolean.TRUE.equals(entry.getValue()))marked++;LinearLayout totals=card();long tracked=PersonalStore.prefs(this).getLong("stat:watchMs",0);totals.addView(Ui.text(this,"Tracked watch time · "+(tracked<60000?tracked/1000+" seconds":tracked/60000+" minutes"),24,Ui.ACCENT));totals.addView(Ui.text(this,LibraryStore.list(this).size()+" saved titles",24,Ui.INK));totals.addView(Ui.text(this,PersonalStore.collections(this).size()+" collections",18,Ui.INK));totals.addView(Ui.text(this,(progress/60000)+" minutes of saved viewing progress",16,Ui.MUTED));totals.addView(Ui.text(this,finished+" finished in retained history · "+marked+" manually marked watched",14,Ui.MUTED));}
