 private void storage(){heading("Space for more stories","Completed downloads and the streaming runtime are kept when you clean temporary update files.");LinearLayout usage=card();usage.addView(Ui.text(this,"Measuring storage…",16,Ui.MUTED));worker.execute(()->{long downloads=StorageTools.size(new File(getFilesDir(),"downloads")),cache=StorageTools.size(getCacheDir()),runtime=StorageTools.size(getCodeCacheDir()),metadata=StorageTools.size(getFilesDir()),external=StorageTools.size(getExternalFilesDir(null)),updates=StorageTools.updates(this);runOnUiThread(()->{if(isDestroyed())return;usage.removeAllViews();usage.addView(Ui.text(this,"Offline videos · "+StorageTools.format(downloads),18,Ui.INK));usage.addView(Ui.text(this,"Other app files · "+StorageTools.format(Math.max(0,metadata-downloads)),14,Ui.MUTED));usage.addView(Ui.text(this,"Temporary cache · "+StorageTools.format(cache)+"\nRuntime files · "+StorageTools.format(runtime)+"\nExternal app files · "+StorageTools.format(external)+"\nUpdate packages · "+StorageTools.format(updates),14,Ui.MUTED));});});Button clean=Ui.primary(this,"Clear expired update files");clean.setOnClickListener(v->execute("Cleaning update files…",()->StorageTools.cleanUpdates(this),result->{render();message("Freed "+StorageTools.format((Long)result),false);}));body.addView(clean);row("↓","Download preferences","Wi-Fi and total storage limit",()->navigate("downloads"));row("▤","Manage offline videos","Review or delete completed downloads",()->startActivity(new Intent(this,DownloadsActivity.class)));}
